from pathlib import Path
import re
patch=Path('/home/drx/.cache/mipstarre-dev/reviews/pr736/8cd8edfa743d5744a9acf0ceee397a45a24310c0/diff.patch').read_text()
chunks={c.splitlines()[0].split(' b/')[1]:c for c in patch.split('diff --git ')[1:]}
newnames={}
for f,c in chunks.items():
 if f.startswith('MIPStarRE/') and f.endswith('.lean'):
  for n in re.findall(r'"'^'"\\+(?:noncomputable )?(?:theorem|def|structure) (["'^'"\\s(:]+)',c,re.M):newnames[n]=f
# Index declarations for all new blueprint links, including qualified methods.
links=[]
for f,c in chunks.items():
 if f.startswith('blueprint/'):
  links.extend(re.findall(r'"'^'"\\+\\\\lean\\{(["'^}]+)'"\\}',c,re.M))
files=list(Path('MIPStarRE').rglob('*.lean'))
idx={}
for f in files:
 for i,line in enumerate(f.read_text().splitlines(),1):
  m=re.match(r'(?:(?:noncomputable|protected|private) )*(?:def|abbrev|theorem|lemma|structure|class) (["'^'"\\s(:]+)',line)
  if m:idx.setdefault(m[1],[]).append((str(f),i))
unknown=[]
for n in links:
 tail=n.split('.')[-1]
 if tail not in idx and not any(n.endswith('.'+k) for k in idx):unknown.append(n)
print('New tags:',len(links),'unresolved by static declaration-name inventory:',unknown)
print('Added packaging phrases:',sum(len(re.findall(r'"'^'"\\+.*Existential packaging',c,re.M)) for f,c in chunks.items() if f.startswith('MIPStarRE/')))
PY"

